<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Bursar'],true)){http_response_code(403);exit('Access denied.');}
if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}
$id=filter_var($_POST['schedule_id']??null,FILTER_VALIDATE_INT);if(!$id){$_SESSION['error']='Select a valid schedule.';header('Location: ../?page=fees&tab=schedules');exit;}
$pdo=db();try{$pdo->beginTransaction();$stmt=$pdo->prepare('SELECT fs.*,t.academic_year,t.starts_on,t.ends_on FROM fee_schedules fs JOIN school_terms t ON t.id=fs.term_id WHERE fs.id=:id AND fs.active=1 FOR UPDATE');$stmt->execute(['id'=>$id]);$s=$stmt->fetch();if(!$s)throw new DomainException('This schedule is unavailable.');$sql="INSERT IGNORE INTO fee_ledger (student_id,term_id,schedule_id,category_id,transaction_type,description,amount,currency,transaction_date,recorded_by) SELECT DISTINCT st.id,:term,:schedule,:category,'Charge',:description,:amount,:currency,CURDATE(),:user FROM students st JOIN student_enrolments e ON e.student_id=st.id WHERE e.academic_year=:year AND e.start_date<=:term_end AND (e.end_date IS NULL OR e.end_date>=:term_start) AND (:form_all=0 OR e.form_level=:form_level)";$insert=$pdo->prepare($sql);$insert->execute(['term'=>$s['term_id'],'schedule'=>$id,'category'=>$s['category_id'],'description'=>$s['description'],'amount'=>$s['amount'],'currency'=>$s['currency'],'user'=>$user['id'],'year'=>$s['academic_year'],'term_start'=>$s['starts_on'],'term_end'=>$s['ends_on'],'form_all'=>$s['form_level'],'form_level'=>$s['form_level']]);$count=$insert->rowCount();if(!$count)throw new DomainException('No learners were enrolled in this form during the selected term, or the schedule was already applied to everyone.');audit_log('fees.schedule_applied','fee_schedules',(int)$id,['charges_created'=>$count]);$pdo->commit();$_SESSION['notice']='Fee schedule applied to '.$count.' learners.';}catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']=$e->getMessage();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Fee schedule apply failed: '.$e->getMessage());$_SESSION['error']='Could not apply the fee schedule.';}
header('Location: ../?page=fees&tab=schedules');exit;
